  <script>
    // FAQ Toggle
    document.querySelectorAll('.faq-question').forEach(button => {
      button.addEventListener('click', () => {
        const item = button.parentElement;
        const isActive = item.classList.contains('active');

        // Close all others
        document.querySelectorAll('.faq-item').forEach(faq => {
          faq.classList.remove('active');
        });

        // Open clicked if it wasn't active
        if (!isActive) {
          item.classList.add('active');
        }
      });
    });

    // Course Filtering
    function filterCourses(category) {
      // Update active tab
      document.querySelectorAll('.tab-btn').forEach(btn => {
        btn.classList.remove('active');
        if (btn.innerText.trim() === category.trim() || btn.innerText.replace('&', '&amp;') === category) {
          btn.classList.add('active');
        }
      });

      // Filter grid
      const cards = document.querySelectorAll('.course-card');
      cards.forEach(card => {
        const cardCategories = card.getAttribute('data-category');
        if (category === 'Featured' || cardCategories.includes(category)) {
          card.style.display = 'flex';
        } else {
          card.style.display = 'none';
        }
      });
    }

    // Duplicate marquee for seamless loop
    const marquee1 = document.getElementById('marquee1');
    const marqueeClone = marquee1.cloneNode(true);
    marqueeClone.id = 'marquee2';
    document.querySelector('.categories-marquee').appendChild(marqueeClone);
    document.querySelector('.categories-marquee').style.display = 'flex';
  </script>
